'use strict';
/**
 * Twin Dial: a twin round-dial instrument cluster (tachometer left, speedometer right) on the G20's 1920x720 panel,
 * drawn through cluster-render with the shared engine (shared/hud.js: the layout apps/twin_dial/hud/layouts/twin.json,
 * made by design/gen_twin.py). docs/twin-dial/SPEC.md is the specification.
 *
 * The centre screen is BMW's own (native RHMI) menu, generated by the kit from app.json "screens" (MAIN): the app's
 * on / off ("Cluster": Twin Dial or BMW's own), the centre page, the status, then the rest of the settings
 * (shared/menu.js). The engine listens to the settings and redraws at once. It keeps running after the screen is
 * closed (OAP apps stay up in the background), so the screen is only needed for changes.
 *
 * Only one cluster app may draw the panel (SPEC 14.5): "Cluster: Off" here drops every layer and asset, and
 * f30_cluster's own "Off" does the same for it; shared/screen.js keeps the two from drawing together.
 */
const mgu = require('./kit/mgu');
const I18N = require('./lang');
const PS = require('./profile_settings');     // r1120 PS: the look and layout settings per driver profile
require('./twin_icons');          // package A1: the app's pictograms join shared/icons.js ICONS (the tab bar's, the message symbols')
const HudApp = require('./hud');
const Menu = require('./menu');

// the tag line the menu shows under the layout name
const TAGS = { twin: 'twin.tag.twin' };       // r1120 LN: a key of shared/i18n/<lang>.json

mgu.run({
    start(ctx) {
        // r1120 LN: the language (setting "Мова / Language", the head unit's): first, so every word below is in it
        try { I18N.attach(ctx); } catch (e) { ctx.log.error('lang: ' + (e && e.stack || e)); }
        let hud;
        try {
            hud = new HudApp(ctx);
        } catch (e) {
            // nothing drawn, but stay up: an exit here would count as a crash on the car
            ctx.log.error('Twin Dial failed to start: ' + (e && e.stack || e));
            return;
        }
        hud.start();
        // r1120 PS: the active driver profile's set (read only from the car; docs/r1120/PS-REPORT.md). A failure leaves one set, as before
        try {
            const ps = PS.attach(ctx);
            if (ps) ctx.ui.onVisible((name, on) => { if (on && name === 'MAIN') ps.kick('menu'); });
        } catch (e) { ctx.log.error('profile settings failed to start: ' + (e && e.stack || e)); }
        ctx.log.info('Twin Dial ' + ((ctx.spec && ctx.spec.version) || '') + ' started');
        // the centre screen: a failure here leaves the cluster drawing (and the kit's own settings rows working)
        try { new Menu(ctx, hud, { tags: TAGS }).start(); } catch (e) { ctx.log.error('menu failed to start: ' + (e && e.stack || e)); }
        process.on('exit', () => { try { hud.stop(); } catch (e) { /* exiting anyway */ } });
    },
});
